def greet(name, prefix='你好'):
    return f'{prefix}，{name}'

print(greet('小明', prefix='早上好'))

def total(*numbers):
    return sum(numbers)

print(total(1, 2, 3))

class Counter:
    def __init__(self):
        self.value = 0

    def increment(self):
        self.value += 1
        return self.value

counter = Counter()
print(counter.increment())

